# hypothesis: type(value) == C narrows an Any value to C in the true branch and leaves it Any otherwise, with a metaclass __eq__ present as a stress case.
from typing import Any, assert_type, reveal_type


class EqualMeta(type):
    def __eq__(cls, other: object) -> bool:
        return True


class Tagged(metaclass=EqualMeta):
    pass


def classify(value: Any) -> str:
    if type(value) == int:
        assert_type(value, int)
        return 'int'
    reveal_type(value)
    return 'other'


def check_tagged(value: Any) -> str:
    if type(value) == Tagged:
        assert_type(value, Tagged)
        return 'tagged'
    return 'not tagged'


def check_not_str(value: Any) -> str:
    if type(value) != str:
        return 'not str'
    assert_type(value, str)
    return 'str'


assert classify(1) == 'int'
assert classify('x') == 'other'
assert check_tagged(Tagged()) == 'tagged'
assert check_not_str(1) == 'not str'
assert check_not_str('s') == 'str'
